# Figure creation for the main paper: Figures 1, 3, 4 and 5 ONLY.
# Figure 2 is generated by 04_figure2_provinces.R.
# The S1 supplement is generated by 03_figureS1.R.
# No plotted values are fitted to a desired visual trajectory.

suppressPackageStartupMessages({
  library(dplyr)
  library(tidyr)
  library(ggplot2)
  library(patchwork)
  library(readr)
})

pd <- readRDS(file.path("output", "plot_data.rds"))
monthly <- pd$monthly_plot_raw
threshold <- pd$threshold_sweep_plot
threshold_r0 <- pd$threshold_R0_long
pct <- pd$pct_plot
PROD_ORDER <- c("Pyrethroid-only nets", "Next-generation nets")
COV_ORDER <- c("25%", "50%", "75%")
product_colors <- c("Pyrethroid-only nets" = "#d55e00",
                    "Next-generation nets" = "#0072b2")
cov_col <- coverage_colors <- c("25%" = "#0072B2", "50%" = "#E69F00",
                     "75%" = "#009E73")
result_colors <- c("Cases averted" = "#405F92",
                   "Deaths averted" = "#84634D")
genotype_colors <- c("SS" = "#5b4d98", "Tc" = "#008f8c",
                     "RR" = "#d77f30")

# Export native plots and their exact numerical input tables.
fig_dir <- "figures"
out_dir <- "output"
dir.create(fig_dir, recursive = TRUE, showWarnings = FALSE)
dir.create(out_dir, recursive = TRUE, showWarnings = FALSE)

save_fig <- function(plot_object, stub, width = 13, height = 6) {
  ggplot2::ggsave(file.path(fig_dir, paste0(stub, ".pdf")),
                  plot_object, width = width, height = height, bg = "white")
  ggplot2::ggsave(file.path(fig_dir, paste0(stub, ".png")),
                  plot_object, width = width, height = height,
                  dpi = 300, bg = "white")
  if (interactive()) print(plot_object)
  invisible(plot_object)
}

# Compatibility with the supplement script.
PUBLICATION_FIG_WIDTH <- 13
PUBLICATION_FIG_HEIGHT_TWO_ROWS <- 10.5
PUBLICATION_ERRORBAR_WIDTH <- 0.4
show_plot <- function(p) if (interactive()) print(p)
theme_pub <- function() {
  theme_classic(base_size = 13) +
    theme(
      panel.border = element_rect(colour = "grey30", fill = NA, linewidth = 0.45),
      axis.line = element_blank(),
      axis.text = element_text(colour = "black", size = 11),
      axis.title = element_text(size = 12),
      plot.title = element_text(size = 12, face = "bold", hjust = 0.5),
      plot.tag = element_text(face = "bold", size = 15),
      plot.tag.position = c(0.02, 0.98),
      legend.position = "bottom",
      legend.title = element_text(size = 11),
      legend.text = element_text(size = 11),
      panel.grid = element_blank()
    )
}

campaign_years_in_simulation <- pd$campaign_marks
# Year axis: time since initial campaign; the first campaign occurs at Year 1.
xscale_year <- function() {
  scale_x_continuous(limits = c(0, 12),
                     breaks = c(0, 1, 4, 7, 10, 12),
                     expand = expansion(mult = c(0, 0.01)))
}
campaign_lines <- function() {
  geom_vline(xintercept = campaign_years_in_simulation,
             colour = "grey70", linetype = "dashed", linewidth = 0.4)
}

# -------------------- FIGURE 1: threshold analysis -------------------------
# Top panels: resistance invasion; bottom: malaria R0 under the three DFEs.
fig1_invasion <- threshold %>%
  transmute(product = as.character(product), coverage,
            median = invasion_R_to_S_m,
            lower = invasion_R_to_S_lo,
            upper = invasion_R_to_S_hi)
fig1_r0 <- threshold_r0 %>%
  mutate(product = as.character(product), genotype = as.character(genotype)) %>%
  filter((genotype != "Tc" | tc_supported),
         is.finite(m), is.finite(lo), is.finite(hi))

readr::write_csv(fig1_invasion, file.path(out_dir, "Figure_1_invasion_data.csv"))
readr::write_csv(fig1_r0, file.path(out_dir, "Figure_1_R0_data.csv"))

make_invasion <- function(product_name) {
  ggplot(filter(fig1_invasion, product == product_name),
         aes(x = coverage * 100, y = median)) +
    geom_ribbon(aes(ymin = lower, ymax = upper),
                fill = "#777777", alpha = 0.19, na.rm = TRUE) +
    geom_hline(yintercept = 0, linetype = "dashed", colour = "grey40") +
    geom_line(colour = product_colors[[product_name]], linewidth = 1,
              na.rm = TRUE) +
    scale_x_continuous(limits = c(0, 75), breaks = seq(0, 75, by = 25)) +
    labs(title = product_name, x = NULL,
         y = "Resistance invasion index (I[R→S])") + theme_pub()
}
make_r0 <- function(product_name) {
  dat <- filter(fig1_r0, product == product_name) %>%
    mutate(genotype = factor(genotype, levels = c("SS", "Tc", "RR")))
  ggplot(dat, aes(x = coverage * 100, y = m, colour = genotype,
                  fill = genotype, group = genotype)) +
    geom_ribbon(aes(ymin = lo, ymax = hi), alpha = 0.12,
                colour = NA, na.rm = TRUE) +
    geom_hline(yintercept = 1, linetype = "dashed", colour = "grey40") +
    geom_line(linewidth = 0.9, na.rm = TRUE) +
    scale_colour_manual(values = genotype_colors,
                        breaks = c("SS", "Tc", "RR"),
                        labels = c("NSS", "NC", "NRR"), name = "Threshold") +
    scale_fill_manual(values = genotype_colors,
                      breaks = c("SS", "Tc", "RR"),
                      labels = c("NSS", "NC", "NRR"), name = "Threshold") +
    scale_x_continuous(limits = c(0, 75), breaks = seq(0, 75, by = 25)) +
    scale_y_continuous(limits = c(0, NA)) +
    labs(x = "Effective ITN coverage (%)", y = "Basic reproduction number (R0)") +
    theme_pub()
}
figure1 <- ((make_invasion(PROD_ORDER[1]) | make_invasion(PROD_ORDER[2])) /
            (make_r0(PROD_ORDER[1]) | make_r0(PROD_ORDER[2]))) +
  plot_layout(guides = "collect") + plot_annotation(tag_levels = "A") &
  theme(legend.position = "bottom")
save_fig(figure1, "Figure_1_invasion_and_R0", height = 9.2)

# -------------------- Figure 3 / 4 helper ----------------------------------
make_timeseries <- function(data, metric = c("prevalence", "qR"),
                            group_by = c("product", "coverage_label"),
                            title = NULL, show_legend = TRUE) {
  metric <- match.arg(metric)
  group_by <- match.arg(group_by)
  cols <- if (group_by == "product") product_colors else coverage_colors
  centre <- paste0(metric, "_m")
  lower <- paste0(metric, "_lo")
  upper <- paste0(metric, "_hi")
  if (metric == "prevalence") {
    ylab <- "Malaria prevalence (%)"
    ys <- scale_y_continuous(limits = c(0, NA),
                             labels = scales::label_number(suffix = "%"))
  } else {
    ylab <- "Resistant allele frequency (qR)"
    ys <- scale_y_continuous(limits = c(0, 1),
                             breaks = seq(0, 1, by = 0.2),
                             labels = scales::label_percent(accuracy = 1))
  }
  p <- ggplot(data, aes(x = ydec, y = .data[[centre]],
                        colour = .data[[group_by]], fill = .data[[group_by]],
                        group = .data[[group_by]])) +
    campaign_lines() +
    geom_ribbon(aes(ymin = .data[[lower]], ymax = .data[[upper]]),
                alpha = 0.15, colour = NA) +
    geom_line(linewidth = 0.95) +
    scale_colour_manual(values = cols,
                         name = if (group_by == "product") "ITN product" else "Cpeak") +
    scale_fill_manual(values = cols,
                      name = if (group_by == "product") "ITN product" else "Cpeak") +
    xscale_year() + ys +
    labs(x = "Year", y = ylab, title = title) + theme_pub()
  if (!show_legend) p <- p + theme(legend.position = "none")
  p
}

# -------------------- FIGURE 3: product comparison at 50% -------------------
fig3_monthly <- monthly %>%
  filter(abs(coverage_target - 0.50) < 1e-8) %>%
  mutate(product = factor(as.character(product), levels = PROD_ORDER))
fig3_pct <- pct %>%
  filter(abs(coverage_target - 0.50) < 1e-8) %>%
  mutate(product = factor(as.character(product), levels = PROD_ORDER))

fig3_bars <- bind_rows(
  fig3_pct %>% transmute(product, outcome = "Cases averted",
                         median = cases_pct_m, lower = cases_pct_lo,
                         upper = cases_pct_hi),
  fig3_pct %>% transmute(product, outcome = "Deaths averted",
                         median = deaths_pct_m, lower = deaths_pct_lo,
                         upper = deaths_pct_hi)
) %>% mutate(outcome = factor(outcome,
                             levels = c("Cases averted", "Deaths averted")))
readr::write_csv(fig3_monthly, file.path(out_dir, "Figure_3_monthly_data.csv"))
readr::write_csv(fig3_bars, file.path(out_dir, "Figure_3_impact_data.csv"))

fig3A <- make_timeseries(fig3_monthly, "prevalence", "product")
fig3B <- make_timeseries(fig3_monthly, "qR", "product")
fig3C <- ggplot(fig3_bars,
                aes(x = product, y = median, fill = outcome, group = outcome)) +
  geom_col(position = position_dodge(width = 0.73), width = 0.65) +
  geom_errorbar(aes(ymin = lower, ymax = upper),
                position = position_dodge(width = 0.73),
                width = 0.18, linewidth = 0.4) +
  scale_fill_manual(values = result_colors, name = "Outcome") +
  scale_y_continuous(limits = c(0, NA),
                     labels = scales::label_number(suffix = "%"),
                     expand = expansion(mult = c(0, 0.08))) +
  labs(x = NULL, y = "Averted over 12 years (%)") +
  theme_pub() +
  theme(axis.text.x = element_text(size = 9),
        axis.text.x.top = element_blank())
figure3 <- (fig3A | fig3B | fig3C) +
  plot_layout(widths = c(1.25, 1.25, 1)) +
  plot_annotation(tag_levels = "A")
save_fig(figure3, "Figure_3_product_comparison_50pct", width = 16, height = 6)

# -------------------- FIGURE 4: 25%, 50%, 75% for each product -------------
fig4_monthly <- monthly %>%
  mutate(product = as.character(product),
         coverage_label = factor(as.character(coverage_label), levels = COV_ORDER))
readr::write_csv(fig4_monthly, file.path(out_dir, "Figure_4_monthly_data.csv"))
py_data <- filter(fig4_monthly, product == PROD_ORDER[1])
ng_data <- filter(fig4_monthly, product == PROD_ORDER[2])
fig4A <- make_timeseries(py_data, "prevalence", "coverage_label",
                         title = "Pyrethroid-only nets")
fig4B <- make_timeseries(py_data, "qR", "coverage_label",
                         title = "Pyrethroid-only nets")
fig4C <- make_timeseries(ng_data, "prevalence", "coverage_label",
                         title = "Next-generation nets")
fig4D <- make_timeseries(ng_data, "qR", "coverage_label",
                         title = "Next-generation nets")
figure4 <- ((fig4A | fig4B) / (fig4C | fig4D)) +
  plot_layout(guides = "collect") + plot_annotation(tag_levels = "A") &
  theme(legend.position = "bottom")
save_fig(figure4, "Figure_4_coverage_comparison", height = 9.7)

# -------------------- FIGURE 5: averted cases / deaths ----------------------
fig5_data <- bind_rows(
  pct %>% transmute(product = factor(as.character(product), levels = PROD_ORDER),
                    coverage_label = factor(as.character(coverage_label), levels = COV_ORDER),
                    outcome = "Cases", median = cases_pct_m,
                    lower = cases_pct_lo, upper = cases_pct_hi),
  pct %>% transmute(product = factor(as.character(product), levels = PROD_ORDER),
                    coverage_label = factor(as.character(coverage_label), levels = COV_ORDER),
                    outcome = "Deaths", median = deaths_pct_m,
                    lower = deaths_pct_lo, upper = deaths_pct_hi)
)
readr::write_csv(fig5_data, file.path(out_dir, "Figure_5_impact_data.csv"))
make_fig5 <- function(outcome_name) {
  ggplot(filter(fig5_data, outcome == outcome_name),
         aes(x = coverage_label, y = median, fill = product, group = product)) +
    geom_col(position = position_dodge(width = 0.7), width = 0.64) +
    geom_errorbar(aes(ymin = lower, ymax = upper),
                  position = position_dodge(width = 0.7),
                  width = 0.14, linewidth = 0.4) +
    scale_fill_manual(values = product_colors, name = "ITN product") +
    scale_y_continuous(limits = c(0, NA),
                       labels = scales::label_number(suffix = "%"),
                       expand = expansion(mult = c(0, 0.07))) +
    labs(x = "Cpeak", y = paste(outcome_name, "averted over 12 years (%)")) +
    theme_pub()
}
figure5 <- (make_fig5("Cases") | make_fig5("Deaths")) +
  plot_layout(guides = "collect") + plot_annotation(tag_levels = "A") &
  theme(legend.position = "bottom")
save_fig(figure5, "Figure_5_public_health_impact", height = 5.8)
message("Main manuscript Figures 1, 3, 4 and 5 saved, with figure-specific CSV files.")
